<?php require __DIR__.'/../app/bootstrap.php';require __DIR__.'/_layout.php';$u=require_admin();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$iid=(int)$_POST['invoice_id'];mark_invoice_paid($iid,'manual','ADMIN');$q=db()->prepare('SELECT order_id FROM invoices WHERE id=?');$q->execute([$iid]);$oid=(int)$q->fetchColumn();if($oid){$sid=ensure_service_for_order($oid);if(($_POST['provision']??'')==='1')provision_service($sid);}$msg='Invoice marked paid'.(($_POST['provision']??'')==='1'?' and provisioning started.':'.');}catch(Throwable $e){$err=$e->getMessage();}}$rows=db()->query("SELECT i.*,u.name customer_name,u.email,o.order_number FROM invoices i JOIN users u ON u.id=i.user_id LEFT JOIN orders o ON o.id=i.order_id ORDER BY i.id DESC")->fetchAll();admin_head($u,'Billing','billing');?><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><section class="card"><div class="cardhead"><b>INVOICES</b><span class="muted"><?=count($rows)?> invoices</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Invoice</th><th>Customer</th><th>Order</th><th>Total</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['invoice_number'])?></b></td><td><?=e($r['customer_name'])?><small><?=e($r['email'])?></small></td><td><?=e($r['order_number']??'—')?></td><td>€<?=number_format((float)$r['total'],2)?></td><td><?=e(date('d M Y',strtotime($r['due_at'])))?></td><td><?=admin_badge($r['status'])?></td><td><?php if($r['status']!=='paid'):?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="invoice_id" value="<?=e($r['id'])?>"><button class="btn primary">Mark paid</button><button class="btn" name="provision" value="1">Paid + provision</button></form><?php else:?><span class="muted small">Paid <?=e($r['paid_at']??'')?></span><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php admin_foot(); ?>
